export function renderCollection(onSelect){
 const section=document.createElement('section');section.className='collection section-width';section.id='colecao';section.setAttribute('aria-labelledby','collection-title');
 section.innerHTML='<div class="section-heading"><div><p class="small-note">Encontre o seu começo</p><h2 id="collection-title">Uma coleção inteira<br>para fazer sua.</h2></div><p>Livros, cartões e convites.<br>Com capivaras. Com pessoas. Com você.</p></div><div class="collection-tabs" aria-label="Filtrar modelos"><button data-filter="all" aria-pressed="true">Todos os modelos</button><button data-filter="livro" aria-pressed="false">Livros</button><button data-filter="cartao" aria-pressed="false">Cartões</button><button data-filter="convite" aria-pressed="false">Convites</button></div><div class="collection-grid"></div>';
 const grid=section.querySelector('.collection-grid');
 for(const model of models){const b=document.createElement('button');b.className='collection-item';b.dataset.model=model.id;b.dataset.kind=model.format;b.setAttribute('aria-pressed','false');b.style.setProperty('--model-color',model.color);const art=document.createElement('span');art.className='collection-art';const sprite=document.createElement('span');sprite.className='sprite people row3';sprite.style.setProperty('--frame-x',(model.tile*100/3)+'%');sprite.setAttribute('aria-hidden','true');art.append(sprite);const text=document.createElement('span');text.className='collection-info';const title=document.createElement('strong');title.textContent=model.title;const desc=document.createElement('span');desc.textContent=model.description;const cta=document.createElement('b');cta.textContent='Personalizar este modelo ↗';text.append(title,desc,cta);b.append(art,text);b.addEventListener('click',()=>onSelect(model));grid.append(b);}
 section.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{section.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));grid.querySelectorAll('[data-model]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.kind!==b.dataset.filter);}));
 document.getElementById('atelier').before(section);
}
